handlers.combine=()=>{const bs=needBodies(2);modal('Combine solids',`<div class="note">Target: the body to modify. Subtraction removes the tool volumes from the target; intersection keeps only common material.</div>${field('operation','Operation','union',{options:[['union','Union — add material'],['subtract','Subtract — remove material'],['intersect','Intersect — common volume']]})}${field('target','Target body',bs[0].id,{options:bs.map(b=>[b.id,b.name])})}${field('keep','Keep tool bodies',false,{type:'checkbox',inline:true})}<div class="small-note">${bs.length} bodies selected. Curves use their current facets; Boolean tolerance is 0.000001 mm.</div>`,async data=>{const target=doc.find(data.get('target')),ordered=[target,...bs.filter(b=>b.id!==target.id)];await runGeometry('boolean',ordered,{operation:data.get('operation')},'Boolean '+data.get('operation'),r=>{if(r.solids[0].polygons.length)doc.find(target.id).solid=r.solids[0];else doc.remove([target.id]);if(!data.has('keep'))doc.remove(ordered.slice(1).map(b=>b.id));});setSelection(doc.find(target.id)?[target.id]:[]);},'Combine');};
