handlers.hole=()=>{const b=selectedOne(),bb=b.solid.bounds;modal('Cut cylindrical hole',`${field('radius','Hole radius (mm)',5,{min:.001})}${field('axis','Direction',2,{options:axisOptions})}${fgrid(...bb.center.map((v,i)=>field(['x','y','z'][i],['Center X','Center Y','Center Z'][i]+' (mm)',v)))}${field('depth','Tool length (mm)',Math.max(...bb.size)+10,{min:.001})}<div class="small-note">The tool is centered at the specified point. Its finite length controls through or partial cuts.</div>`,async data=>{let ax=val(data,'axis',0,2),r=val(data,'radius',.001),h=val(data,'depth',.001),center=['x','y','z'].map(k=>val(data,k));let cutter=cylinder(r,h,[0,0,0],64);if(ax===0)cutter=cutter.transform(M.rotate([0,1,0],Math.PI/2));if(ax===1)cutter=cutter.transform(M.rotate([1,0,0],Math.PI/2));cutter=cutter.translate(center);await runGeometry('boolean',[b,{solid:cutter}],{operation:'subtract'},'Cut hole',result=>doc.find(b.id).solid=result.solids[0]);},'Cut hole');};
handlers.draft=()=>{const b=selectedOne(),m=b.solid.meta;if(m.type!=='box'||m.r)throw Error('Draft supports unrounded box primitives.');modal('Draft box faces',`${field('angle','Draft angle (degrees)',5,{min:-80,max:80})}<div class="note">Creates a ruled taper about the bottom profile. All four side walls taper equally.</div>`,data=>{let a=val(data,'angle',-80,80)*Math.PI/180,delta=2*m.h*Math.tan(a),w=m.w+delta,d=m.d+delta;if(w<=.001||d<=.001)throw Error('The draft collapses the top profile.');let s=loft(rectangleProfile(m.w,m.d),rectangleProfile(w,d),m.h).translate([m.center[0],m.center[1],m.center[2]-m.h/2]);doc.transact('Draft box',()=>doc.find(b.id).solid=s);},'Apply draft');};
