handlers.mass=()=>{const bs=selectedBodies().length?selectedBodies():doc.visible();if(!bs.length)throw Error('There is no geometry to measure.');let volume=0,area=0,mass=0,weighted=[0,0,0];const rows=bs.map(b=>{let m=metrics(b.solid),g=m.volume*MATERIALS[b.material].density;volume+=m.volume;area+=m.area;mass+=g;weighted=V.add(weighted,V.mul(m.centroid,g));return `<tr><td>${esc(b.name)}</td><td>${num(m.volume*unitFactor()**3,2)}</td><td>${num(m.area*unitFactor()**2,2)}</td><td>${num(g,3)}</td></tr>`;}).join(''),center=mass?V.mul(weighted,1/mass):[0,0,0];modal('Mass properties',`<div class="field-grid"><div class="result-card"><div class="big-number" style="font-size:18px">${num(volume*unitFactor()**3,1)}</div><div class="result-label">VOLUME · ${unit(3)}</div></div><div class="result-card"><div class="big-number" style="font-size:18px">${num(area*unitFactor()**2,1)}</div><div class="result-label">AREA · ${unit(2)}</div></div><div class="result-card"><div class="big-number" style="font-size:18px">${num(mass,2)}</div><div class="result-label">MASS · g</div></div></div><p>Mass-weighted centroid: <strong>${center.map(v=>dimension(v,3)).join(', ')} ${doc.units}</strong></p><table><thead><tr><th>Body</th><th>Volume (${unit(3)})</th><th>Area (${unit(2)})</th><th>Mass (g)</th></tr></thead><tbody>${rows}</tbody></table><div class="note" style="margin-top:18px">Float64 integration of oriented triangle shells. Values are approximate for curved shapes. Open or intersecting meshes can produce invalid volume; overlapping bodies are summed, not unioned. Material densities are editable only through the source material table.</div>`,null,'Close',true);};
