  if(!ev.target.closest('#popup'))$('popup').hidden=true;
  if(!el)return;
  if(el.dataset.cmd){await execute(el.dataset.cmd);return;}
  if(el.dataset.paletteCmd){$('palette').close();await execute(el.dataset.paletteCmd);return;}
  if(el.dataset.tab){setTab(el.dataset.tab);return;}
