  if(el.dataset.collapse){const id=el.dataset.collapse;state.collapsed.has(id)?state.collapsed.delete(id):state.collapsed.add(id);renderTree();return;}
  if(el.dataset.visible){doc.transact('Toggle body visibility',()=>{const b=doc.find(el.dataset.visible);b.visible=!b.visible;});return;}
  if(el.dataset.deleteGroup){doc.transact('Delete named selection',()=>doc.groups=doc.groups.filter(g=>g.id!==el.dataset.deleteGroup));return;}
  if(el.dataset.componentSelect){const ids=doc.bodies.filter(b=>b.component===el.dataset.componentSelect).map(b=>b.id);setSelection(ev.ctrlKey||ev.metaKey||ev.shiftKey?[...new Set([...state.selected,...ids])]:ids);return;}
  if(el.dataset.body){const id=el.dataset.body,ids=ev.ctrlKey||ev.metaKey||ev.shiftKey?new Set(state.selected):new Set();if((ev.ctrlKey||ev.metaKey||ev.shiftKey)&&ids.has(id))ids.delete(id);else ids.add(id);setSelection([...ids]);return;}
  if(el.dataset.sketch){if(state.sketch)finishSketch(false);state.tool='select';setSelection([],{sketch:el.dataset.sketch});setTab(state.tab);updateGuides();return;}
